pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        // Ensure no overflow in the loop
        vm.assume(_tos.length <= 100);
        bool success = c.transfer(from, caddress, _tos, v);
        // If transfer returned true, then every individual transferFrom must have succeeded
        // But we can't call transferFrom directly; we can only observe the result of the whole call.
        // The property: transfer never returns true if any internal call would revert.
        // We can check this by replaying each transferFrom call and asserting that they all succeed.
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        for (uint i = 0; i < _tos.length; i++) {
            (bool _s, ) = caddress.call(abi.encodeWithSelector(id, from, _tos[i], v));
            assertTrue(_s, "transferFrom call failed unexpectedly");
        }
    }
}

